const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', msg => { if (msg.type() === 'error') errors.push('CONSOLE: ' + msg.text()); });

  await page.goto('file:///Users/louiskoide/15-0/index.html');
  await page.waitForSelector('.fd-kick', { timeout: 10000 });

  // select Ultra Mode
  await page.click('button:has-text("Ultra Mode")');
  await page.click('.fd-kick');

  // draft 11 players
  for (let i = 0; i < 11; i++) {
    await page.waitForSelector('.fd-cand.elig:not([disabled])', { timeout: 10000 });
    await page.click('.fd-cand.elig:not([disabled])');
    await page.waitForSelector('.fd-slot.hl', { timeout: 10000 });
    await page.click('.fd-slot.hl');
    await page.waitForTimeout(150);
  }

  await page.waitForSelector('button:has-text("Run the simulation")', { timeout: 10000 });
  await page.click('button:has-text("Run the simulation")');

  // now on live sim screen - capture initial state
  await page.waitForSelector('.fd-run', { timeout: 10000 });
  await page.waitForTimeout(500);

  const badge = await page.locator('.fd-mb').allTextContents();
  console.log('MODE BADGES:', badge);

  const runHeader = await page.locator('.fd-run-h').textContent();
  console.log('RUN HEADER:', runHeader);

  const board = await page.locator('.fd-lf-board').textContent().catch(() => null);
  console.log('LIVE BOARD (first game):', board);

  // Now drive through: click "Skip game" repeatedly, and handle gates, until done or safety limit
  let steps = 0;
  while (steps < 60) {
    steps++;
    // check if done (Final Verdict appears)
    const doneVisible = await page.locator('text=Final Verdict').count();
    if (doneVisible > 0) break;

    // handle table gate
    const tableGateBtn = page.locator('.fd-gate .fd-btn');
    if (await tableGateBtn.count() > 0) {
      const txt = await tableGateBtn.first().textContent();
      console.log('GATE BUTTON:', txt);
      await tableGateBtn.first().click();
      await page.waitForTimeout(400);
      continue;
    }

    // handle shootout - just try clicking any visible button inside shootout container
    const shootBtn = page.locator('.fd-pk button, [class*="pk"] button');
    if (await shootBtn.count() > 0) {
      console.log('SHOOTOUT STEP');
      await shootBtn.first().click();
      await page.waitForTimeout(300);
      continue;
    }

    // handle continue button
    const contBtn = page.locator('.fd-continue');
    if (await contBtn.count() > 0) {
      await contBtn.first().click();
      await page.waitForTimeout(400);
      continue;
    }

    // skip game
    const skipBtn = page.locator('.fd-skipgame');
    if (await skipBtn.count() > 0) {
      await skipBtn.first().click();
      await page.waitForTimeout(250);
      continue;
    }

    await page.waitForTimeout(500);
  }

  await page.waitForTimeout(500);
  const finalVerdict = await page.locator('.kick').textContent().catch(() => null);
  console.log('FINAL VERDICT LINE:', finalVerdict);
  const pills = await page.locator('.fd-record-pills').textContent().catch(() => null);
  console.log('RECORD PILLS:', pills);
  const played = await page.locator('.fd-stat .n').allTextContents();
  console.log('STATS:', played);

  console.log('ERRORS:', errors);

  await browser.close();
})();
